// Gelen stringi temizleyip bir sayı döndüren yardımcı fonksiyon
function parseMeasureValue(value: string | number | undefined): number {
    if (typeof value === 'number') {
        return value;
    }
    if (typeof value === 'string') {

        const cleanedValue = value.replace(',', '.');
        const num = Number(cleanedValue);

        return isNaN(num) ? 0 : num;
    }
    return 0; // Tanımsız veya null/undefined durumlar için
}

function compareMeasuresWithToleranceIn_mm(measure1: Measure, measure2: Measure, tolerance: number): boolean {
    const keys: Array<'A' | 'B' | 'C' | 'H'> = ['A', 'B', 'C', 'H'];

    for (const key of keys) {
        const val1 = parseMeasureValue(measure1[key]);
        const val2 = parseMeasureValue(measure2[key]);

        if (Math.abs(val1 - val2) > tolerance) {
            // İlk başarısız olan karşılaştırmada döngüden çık
            return false;
        }
    }

    return true;
}

