brandsCatalog.forEach((item) => {
    if (measureCatalog.find(element => element.yv === item.yv)) {
        const found = measureCatalog.find(element => element.yv === item.yv);
        if (found) {
            if (!found.brand?.includes(item.brand)) {
                found.brand?.push(item.brand);
            }
        }
    }
})

//console.log(measureCatalog);
const brandsCatalogMap = new Map<string, string[]>();
brandsCatalog.forEach((item) => {    
  
    const foundItem = measureCatalog.find(element => element.yv === item.yv);
    
    if (foundItem) {
        // 1. Eğer brand alanı undefined ise, onu boş bir array olarak başlat.
        if (!foundItem.brand) {
            foundItem.brand = []; 
        }
        // 2. Artık brand'in her zaman bir array (string[]) olduğunu biliyoruz.
        // Array'e ekleme yapmadan önce varlığını kontrol et
        if (!foundItem.brand.includes(item.brand)) {
            foundItem.brand.push(item.brand);
        }
    }
});

