type Atak = {
    id: string;
    brand: string[];
    measure: Measure
}

type Measure = {
    A: string;
    B: string;
    C: string;
    H: string;
}

const measureMap: Atak[] = [];
const measureRegex = /\d+(?:[.,]\d+)?(?:X\d+(?:[.,]\d+)?){2,3}/g;


for (const item of rawArray) {
    const words = item.split(' ');

    const brands: string[] = [];
    words.forEach((word) => {
        if (brandList.includes(word)) {
            brands.push(word);
        }
    })

    const key = words[0];
    try {
        const value = item.match(measureRegex)?.[0];
        const measures = value?.split('X')!;
        measureMap.push({ id: key, brand: brands, measure: { A: measures[0], B: measures[1], C: measures[2], H: measures[3] } });
    } catch (error) {
        console.log(error, key);
    }
}

function lookForAnyMatch(list1: string[], list2: string[]): [boolean, string] {
    const set2 = new Set(list2);
    for (const item1 of list1) {
        if (set2.has(item1)) {
            return [true, item1];
        }
    }
    return [false, ''];
}


fs.writeFileSync(path.resolve(__dirname, `AtakWalburg.json`), JSON.stringify(measureMap, null, 2), 'utf-8');
//const jsonData: Atak[] = JSON.parse(fs.readFileSync(path.resolve(__dirname, `AtakWalburg.json`), 'utf-8'));


const matchListObj: { AtakKodu: string, YV_NO: string[], matched: string}[] = [];
measureMap.forEach((atak) => {
    measureCatalog.forEach(yvz => {
        if (compareMeasuresWithToleranceIn_mm(atak.measure, yvz.measure, 1)) {
            const [isMatch, matchedBrand] = lookForAnyMatch(atak.brand, yvz.brand!);
            if (isMatch) {
               
                if(!matchListObj.find((item) => item.AtakKodu === atak.id)) {
                    matchListObj.push({ AtakKodu: atak.id, YV_NO: [yvz.yv], matched: matchedBrand })
                } else {
                    matchListObj.find((item) => item.AtakKodu === atak.id)?.YV_NO.push(yvz.yv);
                }

            }
        }
    })
});

const excelData = matchListObj.map(item => {
    return {
        'Atak Kodu': item.AtakKodu,
        'YV NO': item.YV_NO.join(', '),
        'Eslesen Marka': item.matched
    }
})

fs.writeFileSync(path.resolve(__dirname, `YV-Atak_MatchingList.json`), JSON.stringify(matchListObj, null, 2), 'utf-8');
const wb = xlsx.utils.book_new();
const ws = xlsx.utils.json_to_sheet(excelData, { header: ['Atak Kodu', 'YV NO', 'Eslesen Marka'] });
xlsx.utils.book_append_sheet(wb, ws, "YV-Atak_MatchingList");
xlsx.writeFile(wb, path.resolve(__dirname, `YV-Atak_MatchingList.xlsx`));
